const pl = wb.getWorksheet('PL Recon Items');
const st = wb.getWorksheet('Statement Recon Items');
const plRows = pl.getRange('C2:D2').getValues();
const stRows = st.getRange('F2:I3').getValues();
const plDel = [], stDel = [];
plRows.forEach((p, i) => stRows.forEach((s, j) => {
